contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a deposit amount and then attempts to withdrawAll
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // record contract balance before deposit
        uint cBalanceBefore = address(c).balance;

        // deposit into c as this contract (msg.sender for c will be this contract)
        c.deposit{value: depositAmount}();

        // read credit recorded for this contract (auto-generated getter): credit(address)
        uint recordedCredit = c.credit(address(this));

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record contract balance after withdraw attempt
        uint cBalanceAfter = address(c).balance;

        // General invariant to assert:
        // If withdrawAll did not revert, then c.credit(this) must be zero and the contract's balance
        // must have decreased by at least the recordedCredit (i.e., no increase or creation of funds).
        // If it reverted, we make no further claims (revert allowed).
        assert(reverted || (c.credit(address(this)) == 0 && cBalanceAfter + recordedCredit <= cBalanceBefore));
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

