    constructor(C _c) { c = _c; }

    // single public test function with parameters to exercise deposit and withdrawAll
    function run(uint depositAmount, bool doDeposit) public payable {
        require(true);
        // If we plan to deposit, ensure this contract has enough balance to send to c
        if (doDeposit) {
            // must ensure this contract holds at least depositAmount
            // address(this).balance includes any value sent with this outer call
            require(address(this).balance >= depositAmount);
            c.deposit{value: depositAmount}();
        }

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt, read the stored credit via the public getter
        // Note: credit is not declared public in C, so there is no getter; instead we observe via calling withdrawAll effects.
        // However contract C's mapping credit is private in the given contract. To observe the effect, we use behavior:
        // We try a second withdrawAll; if previous call did not revert then second must either revert or result in zero transfer,
        // but we can instead assert that if first call returned (not reverted) then calling withdrawAll again will not transfer any funds,
        // which we can check by comparing address(c).balance before and after a second call when not reverted.

        // Read C's balance before potential second withdraw
        uint balBefore = address(c).balance;

        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint balAfter = address(c).balance;

        // General rule: If the first withdrawAll call did not revert, then after that call the recorded credit for this contract is zero.
        // We encode this as: if first did not revert, then the second withdrawAll cannot extract any additional Ether from C (balance unchanged)
        // (i.e., balAfter == balBefore). If the first reverted, we make no claim.
        assert(reverted || balAfter == balBefore);
    }

    receive() external payable {}
}

