        // There is no direct getter for mapping credit, but we can observe credit indirectly by:
        // - deposit increases mapping; then after withdrawAll we can try to withdraw again and see whether any Ether transfers occur.
        // To obey constraints, we will observe address(c).balance and address(this).balance before and after withdrawAll

        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

